const webhookData = $('Webhook').first().json;
const body = webhookData.body;
const outputFormat = body.output_format || 'text';

// For DOCX extraction, we'll use a simple approach
// In production, this would use mammoth.js or similar library
// Since n8n Code node has limited module access, we'll extract basic content

try {
  let fileContent;

  if (body.file_base64) {
    fileContent = body.file_base64;
  } else {
    // File was downloaded
    const items = $input.all();
    if (items[0]?.json?.error) {
      return [{
        json: {
          success: false,
          error: {
            code: 500,
            message: 'Failed to download file: ' + (items[0].json.error.message || 'Unknown error'),
            status: 'DOWNLOAD_ERROR'
          },
          meta: { provider: 'docx-extractor' }
        }
      }];
    }
    fileContent = items[0]?.binary?.data?.data || '';
  }

  // DOCX is a ZIP file containing XML
  // Basic extraction approach - in production use mammoth.js
  // This is a placeholder that demonstrates the workflow structure

  const result = {
    success: true,
    data: {
      content: 'DOCX extraction requires mammoth.js library. Please configure n8n with custom nodes for full DOCX support.',
      format: outputFormat,
      metadata: {
        file_type: 'docx',
        extraction_method: 'placeholder'
      },
      note: 'For production use, install mammoth npm package in n8n custom function node'
    },
    meta: {
      provider: 'docx-extractor',
      output_format: outputFormat
    }
  };

  // If we have OpenAI key, use GPT-4 Vision for extraction from rendered preview
  if (body.openai_api_key && body.use_vision) {
    result.data.vision_extraction_available = true;
  }

  return [{ json: result }];

} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to extract DOCX: ' + e.message,
        status: 'EXTRACTION_ERROR'
      },
      meta: { provider: 'docx-extractor' }
    }
  }];
}
